"use client";

import { type CurveFactory, curveLinear, curveNatural } from "d3-shape";
import { type ReactNode, useId, useMemo } from "react";
import {
  type BandFadeEdges,
  type BandFadeStop,
  type BandSegment,
  bandAreaPath,
  bandEdgeClipPath,
  bandEdgePath,
  bandFadeStops,
  bandPixelExtent,
  resolveBandFadeSides,
} from "./band-geometry";
import { chartCssVars, useChartStable, useYScale } from "./chart-context";
import { type PatternPresetId, renderPatternPreset } from "./pattern-preset";
import { useAnimatedBand } from "./use-animated-band";

export type { BandFadeEdges } from "./band-geometry";

export type BandFillType = "solid" | "gradient" | "pattern";

export interface BandStrokeProps {
  /** Default: Band `stroke` ?? `fill`. */
  stroke?: string;
  /** Default: Band `strokeWidth`. */
  strokeWidth?: number;
  /** Default: Band `strokeDasharray`. */
  strokeDasharray?: string;
  /** Default: Band `strokeOpacity`. */
  strokeOpacity?: number;
}

export interface BandProps {
  /** Data key for the band's upper edge. */
  upperKey: string;
  /** Data key for the band's lower edge. */
  lowerKey: string;
  /** Y-scale group id. Default: `"left"`. */
  yAxisId?: string;
  /**
   * Tooltip row label. Default: `"lowerKey – upperKey"` (or the key when both
   * edges share one key).
   */
  label?: string;
  /**
   * Add a `low – high` row (and dots on both edges) to `ChartTooltip`.
   * Default: true
   */
  showInTooltip?: boolean;
  /** Curve function. Default: curveNatural (same as Line). */
  curve?: CurveFactory;
  /** Band colour. Default: var(--chart-line-primary) */
  fill?: string;
  /** Default: `"solid"`. */
  fillType?: BandFillType;
  /** Solid opacity, or gradient opacity at the upper edge. Default: 0.15 */
  fillOpacity?: number;
  /**
   * Fill wherever the upper key drops below the lower key (the two series
   * cross) — e.g. actual below projection, this year behind last year. Uses
   * the same `fillType`, opacities and pattern as `fill`. The colour switches
   * exactly where the edges cross. Default: undefined (one fill throughout).
   */
  negativeFill?: string;
  /** Gradient opacity at the lower edge. Default: 0 */
  gradientToOpacity?: number;
  /** Pattern preset when `fillType` is `"pattern"`. Default: `"diagonal-up"`. */
  pattern?: PatternPresetId;
  /** Default: `fill`. */
  patternColor?: string;
  patternScale?: number;
  patternStrokeWidth?: number;
  /** Opacity applied to the pattern fill. Default: 1 */
  patternOpacity?: number;
  /** Shared edge stroke colour. Default: `fill`. */
  stroke?: string;
  /** Default: 1 */
  strokeWidth?: number;
  /** Default: undefined (solid). */
  strokeDasharray?: string;
  /** Default: 1 */
  strokeOpacity?: number;
  /** `false` hides the top edge; an object overrides the shared stroke. */
  upperStroke?: BandStrokeProps | false;
  /** `false` hides the bottom edge; an object overrides the shared stroke. */
  lowerStroke?: BandStrokeProps | false;
  /**
   * Fade fill and strokes to transparent at the given sides. Horizontal fades
   * span the plot width; vertical fades span the band's own pixel extent.
   * Default: false
   */
  fadeEdges?: BandFadeEdges;
  /** Fraction (0–0.5) of the width / height each fade covers. Default: 0.15 */
  fadeSize?: number;
  className?: string;
}

interface ResolvedBandStroke {
  stroke: string;
  strokeWidth: number;
  strokeDasharray?: string;
  strokeOpacity: number;
}

function resolveEdgeStroke(
  override: BandStrokeProps | false | undefined,
  base: ResolvedBandStroke
): ResolvedBandStroke | null {
  if (override === false) {
    return null;
  }
  const resolved: ResolvedBandStroke = {
    stroke: override?.stroke ?? base.stroke,
    strokeWidth: override?.strokeWidth ?? base.strokeWidth,
    strokeDasharray: override?.strokeDasharray ?? base.strokeDasharray,
    strokeOpacity: override?.strokeOpacity ?? base.strokeOpacity,
  };
  return resolved.strokeWidth > 0 ? resolved : null;
}

function FadeMaskStops({ stops }: { stops: BandFadeStop[] }) {
  return stops.map((stop, index) => (
    <stop
      key={index}
      offset={stop.offset}
      style={{ stopColor: "white", stopOpacity: stop.opacity }}
    />
  ));
}

interface BandAreaFillStyle {
  /** `"gradient"` only when the band has a vertical extent. */
  fillType: BandFillType;
  extent: { top: number; bottom: number } | null;
  fillOpacity: number;
  gradientToOpacity: number;
  pattern: PatternPresetId;
  /** Pattern colour override; falls back to the layer colour. */
  patternColor?: string;
  patternScale?: number;
  patternStrokeWidth?: number;
  patternOpacity: number;
}

/** The band area in one colour, with its own gradient / pattern defs. */
function BandAreaFill({
  d,
  color,
  clipPath,
  style,
}: {
  d: string;
  color: string;
  clipPath?: string;
  style: BandAreaFillStyle;
}) {
  const uniqueId = useId().replace(/:/g, "");
  const paintId = `chart-band-paint-${uniqueId}`;
  const { extent } = style;
  const usesPattern = style.fillType === "pattern" && style.pattern !== "none";
  const usesGradient = style.fillType === "gradient" && extent != null;

  let paint: ReactNode = null;
  let fill = color;
  let opacity = style.fillOpacity;
  if (usesPattern) {
    paint = renderPatternPreset(style.pattern, paintId, {
      color: style.patternColor ?? color,
      scale: style.patternScale,
      strokeWidth: style.patternStrokeWidth,
    });
    fill = `url(#${paintId})`;
    opacity = style.patternOpacity;
  } else if (usesGradient) {
    paint = (
      <linearGradient
        gradientUnits="userSpaceOnUse"
        id={paintId}
        x1={0}
        x2={0}
        y1={extent.top}
        y2={extent.bottom}
      >
        <stop
          offset={0}
          style={{ stopColor: color, stopOpacity: style.fillOpacity }}
        />
        <stop
          offset={1}
          style={{ stopColor: color, stopOpacity: style.gradientToOpacity }}
        />
      </linearGradient>
    );
    fill = `url(#${paintId})`;
    opacity = 1;
  }

  return (
    <>
      {paint ? <defs>{paint}</defs> : null}
      <path clipPath={clipPath} d={d} fill={fill} fillOpacity={opacity} />
    </>
  );
}

/**
 * `negativeFill`: the area drawn twice, clipped above the lower edge in `fill`
 * and below it in `negativeFill`, so the colour flips where the edges cross.
 */
function BandSplitFill({
  d,
  fill,
  negativeFill,
  segments,
  curve,
  innerHeight,
  style,
}: {
  d: string;
  fill: string;
  negativeFill: string;
  segments: BandSegment[];
  curve: CurveFactory;
  innerHeight: number;
  style: BandAreaFillStyle;
}) {
  const uniqueId = useId().replace(/:/g, "");
  const aboveId = `chart-band-above-${uniqueId}`;
  const belowId = `chart-band-below-${uniqueId}`;
  const clips = useMemo(() => {
    // Far enough past the plot that a panned / overshooting band stays inside.
    const far = Math.max(innerHeight, 1) * 3;
    return {
      above: bandEdgeClipPath(segments, "lower", "above", curve, far),
      below: bandEdgeClipPath(segments, "lower", "below", curve, far),
    };
  }, [segments, curve, innerHeight]);

  return (
    <>
      <defs>
        <clipPath id={aboveId}>
          <path d={clips.above} />
        </clipPath>
        <clipPath id={belowId}>
          <path d={clips.below} />
        </clipPath>
      </defs>
      <BandAreaFill
        clipPath={`url(#${aboveId})`}
        color={fill}
        d={d}
        style={style}
      />
      <BandAreaFill
        clipPath={`url(#${belowId})`}
        color={negativeFill}
        d={d}
        style={{ ...style, patternColor: undefined }}
      />
    </>
  );
}

/** Phases where series strokes are drawn (matches `<Line>`). */
function isBandVisiblePhase(phase: string): boolean {
  return phase === "revealing" || phase === "ready" || phase === "exitingReady";
}

export function Band({
  upperKey,
  lowerKey,
  yAxisId,
  // `label` / `showInTooltip` are read from props by the chart shell
  // (`extractBandConfigs`) for tooltip rows.
  curve = curveNatural,
  fill = chartCssVars.linePrimary,
  fillType = "solid",
  fillOpacity = 0.15,
  negativeFill,
  gradientToOpacity = 0,
  pattern = "diagonal-up",
  patternColor,
  patternScale,
  patternStrokeWidth,
  patternOpacity = 1,
  stroke,
  strokeWidth = 1,
  strokeDasharray,
  strokeOpacity = 1,
  upperStroke,
  lowerStroke,
  fadeEdges = false,
  fadeSize = 0.15,
  className,
}: BandProps) {
  const {
    renderData,
    xScale,
    innerWidth,
    innerHeight,
    xAccessor,
    chartPhase,
    yDomainTweenDuration,
  } = useChartStable();
  const yScale = useYScale(yAxisId);

  // Same tween inputs as `<Line>` (animate + ready phase, yDomainTweenDuration)
  // so band edges morph in lockstep with lines on data changes.
  const displayed = useAnimatedBand({
    chartPhase,
    curve,
    durationMs: yDomainTweenDuration,
    enabled: chartPhase === "ready",
    innerWidth,
    lowerKey,
    renderData,
    upperKey,
    xAccessor,
    xScale,
    yScale,
  });
  const { segments, polyline } = displayed;

  const paths = useMemo(() => {
    const pathCurve = polyline ? curveLinear : curve;
    return {
      area: bandAreaPath(segments, pathCurve),
      upper: bandEdgePath(segments, "upper", pathCurve),
      lower: bandEdgePath(segments, "lower", pathCurve),
      extent: bandPixelExtent(segments),
    };
  }, [segments, polyline, curve]);

  const uniqueId = useId().replace(/:/g, "");
  const hMaskId = `chart-band-fade-x-${uniqueId}`;
  const vMaskId = `chart-band-fade-y-${uniqueId}`;

  if (!isBandVisiblePhase(chartPhase) || paths.area === "") {
    return null;
  }

  const { extent } = paths;
  const hasExtent = extent != null && extent.bottom - extent.top > 0;
  const fadeSides = resolveBandFadeSides(fadeEdges);
  const fadeX = fadeSides.horizontal && innerWidth > 0;
  const fadeY = fadeSides.vertical && hasExtent;
  const fillStyle: BandAreaFillStyle = {
    extent: hasExtent ? extent : null,
    fillOpacity,
    fillType,
    gradientToOpacity,
    pattern,
    patternColor,
    patternOpacity,
    patternScale,
    patternStrokeWidth,
  };

  const baseStroke: ResolvedBandStroke = {
    stroke: stroke ?? fill,
    strokeWidth,
    strokeDasharray,
    strokeOpacity,
  };
  const upperEdge = resolveEdgeStroke(upperStroke, baseStroke);
  const lowerEdge = resolveEdgeStroke(lowerStroke, baseStroke);

  // Generous user-space mask region: series extend past the plot while an
  // `xDomain` viewport pans; the gradients pad their end stops beyond it.
  const maskRegion = {
    height: innerHeight * 3,
    maskUnits: "userSpaceOnUse" as const,
    width: innerWidth * 3,
    x: -innerWidth,
    y: -innerHeight,
  };
  const maskRect = {
    height: maskRegion.height,
    width: maskRegion.width,
    x: maskRegion.x,
    y: maskRegion.y,
  };

  const content = (
    <>
      {negativeFill ? (
        <BandSplitFill
          curve={polyline ? curveLinear : curve}
          d={paths.area}
          fill={fill}
          innerHeight={innerHeight}
          negativeFill={negativeFill}
          segments={segments}
          style={fillStyle}
        />
      ) : (
        <BandAreaFill color={fill} d={paths.area} style={fillStyle} />
      )}
      {lowerEdge ? (
        <path
          d={paths.lower}
          fill="none"
          stroke={lowerEdge.stroke}
          strokeDasharray={lowerEdge.strokeDasharray}
          strokeLinecap="round"
          strokeOpacity={lowerEdge.strokeOpacity}
          strokeWidth={lowerEdge.strokeWidth}
        />
      ) : null}
      {upperEdge ? (
        <path
          d={paths.upper}
          fill="none"
          stroke={upperEdge.stroke}
          strokeDasharray={upperEdge.strokeDasharray}
          strokeLinecap="round"
          strokeOpacity={upperEdge.strokeOpacity}
          strokeWidth={upperEdge.strokeWidth}
        />
      ) : null}
    </>
  );

  return (
    // biome-ignore lint/a11y/noAriaHiddenOnFocusable: decorative band
    <g
      aria-hidden="true"
      className={className ?? "chart-band"}
      pointerEvents="none"
    >
      <defs>
        {fadeX ? (
          <>
            <linearGradient
              gradientUnits="userSpaceOnUse"
              id={`${hMaskId}-gradient`}
              x1={0}
              x2={innerWidth}
              y1={0}
              y2={0}
            >
              <FadeMaskStops
                stops={bandFadeStops(fadeSides.left, fadeSides.right, fadeSize)}
              />
            </linearGradient>
            <mask id={hMaskId} {...maskRegion}>
              <rect fill={`url(#${hMaskId}-gradient)`} {...maskRect} />
            </mask>
          </>
        ) : null}
        {fadeY && extent ? (
          <>
            <linearGradient
              gradientUnits="userSpaceOnUse"
              id={`${vMaskId}-gradient`}
              x1={0}
              x2={0}
              y1={extent.top}
              y2={extent.bottom}
            >
              <FadeMaskStops
                stops={bandFadeStops(fadeSides.top, fadeSides.bottom, fadeSize)}
              />
            </linearGradient>
            <mask id={vMaskId} {...maskRegion}>
              <rect fill={`url(#${vMaskId}-gradient)`} {...maskRect} />
            </mask>
          </>
        ) : null}
      </defs>
      <g mask={fadeX ? `url(#${hMaskId})` : undefined}>
        <g mask={fadeY ? `url(#${vMaskId})` : undefined}>{content}</g>
      </g>
    </g>
  );
}

Band.displayName = "Band";

export default Band;

import { type CurveFactory, area as d3Area, line as d3Line } from "d3-shape";
import {
  flattenSeriesPath,
  interpolateSeriesPathPoints,
  type SeriesPathPoint,
  samplePolylineY,
} from "./series-path-utils";

/** One plotted row of a band, in pixels. */
export interface BandPoint {
  x: number;
  upper: number;
  lower: number;
  key: string;
}

/** Contiguous run of defined rows (gaps split the band into segments). */
export type BandSegment = BandPoint[];

function finiteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

/**
 * Pixel band segments. Rows where either edge is null / undefined / NaN end
 * the current segment (e.g. Bollinger warm-up rows).
 */
export function computeBandSegments(
  data: Record<string, unknown>[],
  xAccessor: (datum: Record<string, unknown>) => Date,
  xScale: (value: Date) => number | undefined,
  yScale: (value: number) => number | undefined,
  upperKey: string,
  lowerKey: string
): BandSegment[] {
  const segments: BandSegment[] = [];
  let current: BandSegment = [];

  data.forEach((datum, index) => {
    const upper = datum[upperKey];
    const lower = datum[lowerKey];
    if (!(finiteNumber(upper) && finiteNumber(lower))) {
      if (current.length > 0) {
        segments.push(current);
        current = [];
      }
      return;
    }
    const xValue = xAccessor(datum);
    current.push({
      x: xScale(xValue) ?? 0,
      upper: yScale(upper) ?? 0,
      lower: yScale(lower) ?? 0,
      key: String(xValue.getTime?.() ?? index),
    });
  });

  if (current.length > 0) {
    segments.push(current);
  }
  return segments;
}

function edgePoints(
  segment: BandSegment,
  edge: "upper" | "lower"
): SeriesPathPoint[] {
  return segment.map((point) => ({
    x: point.x,
    y: point[edge],
    key: point.key,
  }));
}

/** Closed area path between the edges, one sub-path per segment. */
export function bandAreaPath(
  segments: BandSegment[],
  curve: CurveFactory
): string {
  const generator = d3Area<BandPoint>()
    .x((point) => point.x)
    .y0((point) => point.lower)
    .y1((point) => point.upper)
    .curve(curve);
  return segments
    .filter((segment) => segment.length > 1)
    .map((segment) => generator(segment) ?? "")
    .join("");
}

/** Open stroke path along one edge, one sub-path per segment. */
export function bandEdgePath(
  segments: BandSegment[],
  edge: "upper" | "lower",
  curve: CurveFactory
): string {
  const generator = d3Line<BandPoint>()
    .x((point) => point.x)
    .y((point) => point[edge])
    .curve(curve);
  return segments
    .filter((segment) => segment.length > 1)
    .map((segment) => generator(segment) ?? "")
    .join("");
}

/**
 * Clip region on one side of a band edge: each segment's edge curve, closed
 * `far` px off the top (`"above"`) or bottom (`"below"`) of the plot. Used by
 * `negativeFill` to split the fill where the upper key crosses the lower key.
 */
export function bandEdgeClipPath(
  segments: BandSegment[],
  edge: "upper" | "lower",
  side: "above" | "below",
  curve: CurveFactory,
  far: number
): string {
  const generator = d3Line<BandPoint>()
    .x((point) => point.x)
    .y((point) => point[edge])
    .curve(curve);
  const y = side === "above" ? -far : far;
  return segments
    .filter((segment) => segment.length > 1)
    .map((segment) => {
      const path = generator(segment);
      const first = segment[0];
      const last = segment.at(-1);
      if (!(path && first && last)) {
        return "";
      }
      return `${path}L${last.x},${y}L${first.x},${y}Z`;
    })
    .join("");
}

/** Vertical pixel extent covered by both edges (top < bottom in SVG space). */
export function bandPixelExtent(
  segments: BandSegment[]
): { top: number; bottom: number } | null {
  let top = Number.POSITIVE_INFINITY;
  let bottom = Number.NEGATIVE_INFINITY;
  for (const segment of segments) {
    for (const point of segment) {
      top = Math.min(top, point.upper, point.lower);
      bottom = Math.max(bottom, point.upper, point.lower);
    }
  }
  return Number.isFinite(top) ? { top, bottom } : null;
}

/** Dense polylines of both edges, all segments concatenated and sorted by x. */
export interface BandEdgePolylines {
  upper: SeriesPathPoint[];
  lower: SeriesPathPoint[];
}

export function flattenBandEdges(
  segments: BandSegment[],
  curve: CurveFactory,
  alreadyPolyline: boolean
): BandEdgePolylines {
  const flatten = (edge: "upper" | "lower") =>
    segments
      .flatMap((segment) => {
        const points = edgePoints(segment, edge);
        return alreadyPolyline ? points : flattenSeriesPath(points, curve);
      })
      .sort((a, b) => a.x - b.x);
  return { upper: flatten("upper"), lower: flatten("lower") };
}

/**
 * Vertical morph (same approach as `morphSeriesPolylines`): both edges are
 * sampled on a shared x grid per target segment and only y is interpolated,
 * so the band rises and falls into shape alongside morphing lines. Result is
 * a polyline — render with `curveLinear`.
 */
export function morphBandSegments(
  from: BandEdgePolylines,
  targets: BandSegment[],
  curve: CurveFactory,
  progress: number,
  sampleSpacingPx = 2
): BandSegment[] {
  if (from.upper.length === 0 || from.lower.length === 0) {
    return targets;
  }
  return targets.map((segment) => {
    const first = segment[0];
    const last = segment.at(-1);
    if (!(first && last) || segment.length < 2) {
      return segment;
    }
    const toUpper = flattenSeriesPath(edgePoints(segment, "upper"), curve);
    const toLower = flattenSeriesPath(edgePoints(segment, "lower"), curve);
    const span = last.x - first.x;
    const count = Math.max(2, Math.ceil(span / sampleSpacingPx) + 1);
    const result: BandSegment = new Array(count);
    for (let index = 0; index < count; index++) {
      const x = first.x + (span * index) / (count - 1);
      const fromUpper = samplePolylineY(from.upper, x);
      const fromLower = samplePolylineY(from.lower, x);
      result[index] = {
        x,
        upper: fromUpper + (samplePolylineY(toUpper, x) - fromUpper) * progress,
        lower: fromLower + (samplePolylineY(toLower, x) - fromLower) * progress,
        key: "",
      };
    }
    return result;
  });
}

/**
 * Keyed slide (same approach as `interpolateSeriesPathPoints`) for viewport
 * changes on unchanged data, e.g. brush pan / resize.
 */
export function interpolateBandSegments(
  from: BandSegment[],
  targets: BandSegment[],
  progress: number
): BandSegment[] {
  if (progress >= 1 || from.length === 0) {
    return targets;
  }
  const fromUpper = from.flatMap((segment) => edgePoints(segment, "upper"));
  const fromLower = from.flatMap((segment) => edgePoints(segment, "lower"));
  return targets.map((segment) => {
    const upper = interpolateSeriesPathPoints(
      fromUpper,
      edgePoints(segment, "upper"),
      progress
    );
    const lower = interpolateSeriesPathPoints(
      fromLower,
      edgePoints(segment, "lower"),
      progress
    );
    return upper.map((point, index) => ({
      x: point.x,
      upper: point.y,
      lower: lower[index]?.y ?? point.y,
      key: point.key,
    }));
  });
}

/** Signature of both edge values per row (ignores scales / width). */
export function bandDataSignature(
  renderData: Record<string, unknown>[],
  xAccessor: (datum: Record<string, unknown>) => Date,
  upperKey: string,
  lowerKey: string
): string {
  return renderData
    .map((datum) => {
      const upper = datum[upperKey];
      const lower = datum[lowerKey];
      return `${xAccessor(datum).getTime()}:${finiteNumber(upper) ? upper : ""}:${finiteNumber(lower) ? lower : ""}`;
    })
    .join(",");
}

export type BandFadeEdges =
  | boolean
  | "left"
  | "right"
  | { top?: boolean; right?: boolean; bottom?: boolean; left?: boolean };

export interface BandFadeSides {
  top: boolean;
  right: boolean;
  bottom: boolean;
  left: boolean;
  horizontal: boolean;
  vertical: boolean;
}

export function resolveBandFadeSides(
  fade: BandFadeEdges | undefined
): BandFadeSides {
  let sides = { top: false, right: false, bottom: false, left: false };
  if (fade === true) {
    sides = { top: true, right: true, bottom: true, left: true };
  } else if (fade === "left") {
    sides.left = true;
  } else if (fade === "right") {
    sides.right = true;
  } else if (fade && typeof fade === "object") {
    sides = {
      top: fade.top === true,
      right: fade.right === true,
      bottom: fade.bottom === true,
      left: fade.left === true,
    };
  }
  return {
    ...sides,
    horizontal: sides.left || sides.right,
    vertical: sides.top || sides.bottom,
  };
}

export interface BandFadeStop {
  offset: number;
  opacity: number;
}

/**
 * Mask stops along one axis: transparent at faded ends, opaque in between.
 * `size` is the fraction (0–0.5) of the axis each fade occupies.
 */
export function bandFadeStops(
  startFaded: boolean,
  endFaded: boolean,
  size: number
): BandFadeStop[] {
  const span = Math.min(0.5, Math.max(0, size));
  return [
    { offset: 0, opacity: startFaded ? 0 : 1 },
    { offset: span, opacity: 1 },
    { offset: 1 - span, opacity: 1 },
    { offset: 1, opacity: endFaded ? 0 : 1 },
  ];
}

"use client";

import type { CurveFactory } from "d3-shape";
import { animate, useReducedMotion } from "motion/react";
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import {
  type BandSegment,
  bandDataSignature,
  computeBandSegments,
  flattenBandEdges,
  interpolateBandSegments,
  morphBandSegments,
} from "./band-geometry";
import { LINE_LOADING_PULSE_EASE } from "./line-loading-timing";

export interface UseAnimatedBandOptions {
  renderData: Record<string, unknown>[];
  xAccessor: (datum: Record<string, unknown>) => Date;
  xScale: (value: Date) => number | undefined;
  yScale: (value: number) => number | undefined;
  upperKey: string;
  lowerKey: string;
  curve: CurveFactory;
  chartPhase: string;
  durationMs: number;
  innerWidth: number;
  enabled: boolean;
}

/** Band currently on screen. `polyline` frames render with `curveLinear`. */
export interface DisplayedBand {
  segments: BandSegment[];
  polyline: boolean;
}

type LatestBandInputs = Pick<
  UseAnimatedBandOptions,
  | "renderData"
  | "xAccessor"
  | "xScale"
  | "yScale"
  | "upperKey"
  | "lowerKey"
  | "curve"
>;

function segmentsFor(inputs: LatestBandInputs): BandSegment[] {
  return computeBandSegments(
    inputs.renderData,
    inputs.xAccessor,
    inputs.xScale,
    inputs.yScale,
    inputs.upperKey,
    inputs.lowerKey
  );
}

/**
 * Band counterpart of `useAnimatedSeriesPath`: same trigger signatures,
 * duration (`yDomainTweenDuration`), easing and morph-vs-slide rule, so a
 * band tweens frame-for-frame with the `<Line>`s it is composed with.
 */
export function useAnimatedBand({
  renderData,
  xAccessor,
  xScale,
  yScale,
  upperKey,
  lowerKey,
  curve,
  chartPhase,
  durationMs,
  innerWidth,
  enabled,
}: UseAnimatedBandOptions): DisplayedBand {
  const reducedMotion = useReducedMotion();
  const [animatedBand, setAnimatedBand] = useState<DisplayedBand | null>(null);
  const displayedRef = useRef<DisplayedBand | null>(null);
  const animatingRef = useRef(false);

  const xScaleDomain = useMemo(() => {
    const scaleWithDomain = xScale as { domain?: () => [Date, Date] };
    return scaleWithDomain.domain?.() ?? [new Date(0), new Date(0)];
  }, [xScale]);

  const dataSignature = useMemo(
    () => bandDataSignature(renderData, xAccessor, upperKey, lowerKey),
    [renderData, xAccessor, upperKey, lowerKey]
  );

  const transitionSignature = `${innerWidth}|${xScaleDomain[0]?.getTime?.() ?? 0}|${xScaleDomain[1]?.getTime?.() ?? 0}|${dataSignature}`;

  const targetSegments = useMemo(
    () =>
      segmentsFor({
        curve,
        lowerKey,
        renderData,
        upperKey,
        xAccessor,
        xScale,
        yScale,
      }),
    [renderData, xAccessor, xScale, yScale, upperKey, lowerKey, curve]
  );

  const prevTransitionSignatureRef = useRef(transitionSignature);
  const prevDataSignatureRef = useRef(dataSignature);

  // Live inputs for the running tween — the y-domain tween rebuilds `yScale`
  // every frame, so these must not be effect deps (see useAnimatedSeriesPath).
  const latestRef = useRef<LatestBandInputs>({
    renderData,
    xAccessor,
    xScale,
    yScale,
    upperKey,
    lowerKey,
    curve,
  });
  // Synced in a layout effect declared before the tween effect (not during
  // render) so `renderFrame(0)` and every animation frame see this commit's
  // inputs.
  useLayoutEffect(() => {
    latestRef.current = {
      renderData,
      xAccessor,
      xScale,
      yScale,
      upperKey,
      lowerKey,
      curve,
    };
  });

  const shouldAnimate =
    enabled &&
    !reducedMotion &&
    chartPhase === "ready" &&
    durationMs > 0 &&
    renderData.length > 0;

  // Drop a stale tween frame as soon as animation is no longer allowed —
  // adjusted during render rather than via setState in the effect below.
  if (!shouldAnimate && animatedBand !== null) {
    setAnimatedBand(null);
  }

  // Scales / targets are read live via latestRef: only a new signature should
  // restart the tween (a dep on per-frame `yScale` would stop it each frame).
  useLayoutEffect(() => {
    const computeLatestTarget = () => segmentsFor(latestRef.current);

    const dataChanged = prevDataSignatureRef.current !== dataSignature;
    prevDataSignatureRef.current = dataSignature;

    if (!shouldAnimate) {
      animatingRef.current = false;
      displayedRef.current = {
        segments: computeLatestTarget(),
        polyline: false,
      };
      prevTransitionSignatureRef.current = transitionSignature;
      return;
    }

    if (prevTransitionSignatureRef.current === transitionSignature) {
      return;
    }
    prevTransitionSignatureRef.current = transitionSignature;

    const from = displayedRef.current ?? {
      segments: computeLatestTarget(),
      polyline: false,
    };
    if (from.segments.length === 0) {
      displayedRef.current = {
        segments: computeLatestTarget(),
        polyline: false,
      };
      return;
    }

    animatingRef.current = true;
    const morph = dataChanged || from.polyline;
    const fromPolylines = morph
      ? flattenBandEdges(from.segments, latestRef.current.curve, from.polyline)
      : null;

    const renderFrame = (progress: number) => {
      const currentTarget = computeLatestTarget();
      const next: DisplayedBand = fromPolylines
        ? {
            segments: morphBandSegments(
              fromPolylines,
              currentTarget,
              latestRef.current.curve,
              progress
            ),
            polyline: true,
          }
        : {
            segments: interpolateBandSegments(
              from.segments,
              currentTarget,
              progress
            ),
            polyline: false,
          };
      displayedRef.current = next;
      setAnimatedBand(next);
    };
    renderFrame(0);

    const control = animate(0, 1, {
      duration: durationMs / 1000,
      ease: [...LINE_LOADING_PULSE_EASE],
      onUpdate: renderFrame,
      onComplete: () => {
        animatingRef.current = false;
        displayedRef.current = {
          segments: computeLatestTarget(),
          polyline: false,
        };
        setAnimatedBand(null);
      },
    });

    return () => {
      control.stop();
      animatingRef.current = false;
    };
  }, [
    transitionSignature,
    dataSignature,
    shouldAnimate,
    chartPhase,
    durationMs,
    enabled,
    reducedMotion,
    renderData.length,
  ]);

  // After the tween effect: a data change needs the previously displayed
  // segments as its `from`, not the new target.
  useEffect(() => {
    if (!animatingRef.current) {
      displayedRef.current = { segments: targetSegments, polyline: false };
    }
  }, [targetSegments]);

  return animatedBand ?? { segments: targetSegments, polyline: false };
}

export interface BollingerBandsOptions {
  /** Numeric key to compute bands for. */
  dataKey: string;
  /** Rolling window length. Default: 20 */
  period?: number;
  /** Standard deviations above / below the SMA. Default: 2 */
  multiplier?: number;
  /**
   * Minimum finite values in the window needed to emit a row (pandas
   * `min_periods`). Clamped to [1, `period`]. Default: `period` — a gap until
   * the window fills. Use `1` to warm up from the first row over a partial
   * window.
   */
  minPeriods?: number;
  /** Default: `${dataKey}Upper` */
  upperKey?: string;
  /** Default: `${dataKey}Lower` */
  lowerKey?: string;
  /** Default: `${dataKey}Sma` */
  middleKey?: string;
}

/**
 * Adds Bollinger band keys to each row: rolling SMA over the last `period`
 * rows ± `multiplier` × population standard deviation, computed over the
 * finite numeric values in that window. Rows whose window has fewer than
 * `minPeriods` such values (by default: before the window fills, or when it
 * contains a non-numeric value) get `null` for all three keys, which
 * `<Band>` / `<Line>` treat as gaps.
 */
export function withBollingerBands<T extends Record<string, unknown>>(
  data: T[],
  options: BollingerBandsOptions
): (T & Record<string, number | null>)[] {
  const {
    dataKey,
    period = 20,
    multiplier = 2,
    upperKey = `${dataKey}Upper`,
    lowerKey = `${dataKey}Lower`,
    middleKey = `${dataKey}Sma`,
    minPeriods = period,
  } = options;
  const windowSize = Math.max(1, Math.floor(period));
  const requiredCount = Math.min(
    windowSize,
    Math.max(
      1,
      Number.isFinite(minPeriods) ? Math.floor(minPeriods) : windowSize
    )
  );

  return data.map((row, index) => {
    let upper: number | null = null;
    let lower: number | null = null;
    let middle: number | null = null;

    const values: number[] = [];
    for (
      let offset = Math.max(0, index - windowSize + 1);
      offset <= index;
      offset++
    ) {
      const value = data[offset]?.[dataKey];
      if (typeof value === "number" && Number.isFinite(value)) {
        values.push(value);
      }
    }
    if (values.length >= requiredCount) {
      const count = values.length;
      const mean = values.reduce((sum, value) => sum + value, 0) / count;
      const variance =
        values.reduce((sum, value) => sum + (value - mean) ** 2, 0) / count;
      const spread = multiplier * Math.sqrt(variance);
      middle = mean;
      upper = mean + spread;
      lower = mean - spread;
    }

    return {
      ...row,
      [upperKey]: upper,
      [lowerKey]: lower,
      [middleKey]: middle,
    } as T & Record<string, number | null>;
  });
}
